def match(orders):
    trades = []
    buy_book = []  # (price, arrival_time, id, qty) - max heap by price (negate), then min by arrival_time
    sell_book = []  # (price, arrival_time, id, qty) - min heap by price, then min by arrival_time
    order_status = {}  # id -> (side, remaining_qty, arrival_time, price) or None if cancelled/filled
    arrival_time = 0

    def add_to_buy_book(price, id, qty):
        import heapq
        heapq.heappush(buy_book, (-price, arrival_time, id, qty))
        order_status[id] = ('buy', qty, arrival_time, price)

    def add_to_sell_book(price, id, qty):
        import heapq
        heapq.heappush(sell_book, (price, arrival_time, id, qty))
        order_status[id] = ('sell', qty, arrival_time, price)

    def match_buy(id, price, qty, is_ioc=False):
        nonlocal trades, sell_book, arrival_time
        import heapq

        while qty > 0 and sell_book:
            # Peek at best sell (lowest price)
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

            if sell_price <= price:
                # Match
                heapq.heappop(sell_book)

                trade_qty = min(qty, sell_qty)
                trades.append([id, sell_id, sell_price, trade_qty])

                qty -= trade_qty
                sell_qty -= trade_qty

                if sell_qty > 0:
                    # Resting sell order partially filled, push back
                    heapq.heappush(sell_book, (sell_price, sell_arrival, sell_id, sell_qty))
                    order_status[sell_id] = ('sell', sell_qty, sell_arrival, sell_price)
                else:
                    # Resting sell order fully filled
                    order_status[sell_id] = None
            else:
                break

        # If limit order, add remainder to book
        if qty > 0 and not is_ioc:
            add_to_buy_book(price, id, qty)
        else:
            if qty == 0:
                order_status[id] = None
            elif is_ioc:
                order_status[id] = None

    def match_sell(id, price, qty, is_ioc=False):
        nonlocal trades, buy_book, arrival_time
        import heapq

        while qty > 0 and buy_book:
            # Peek at best buy (highest price)
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

            if buy_price >= price:
                # Match
                heapq.heappop(buy_book)

                trade_qty = min(qty, buy_qty)
                trades.append([buy_id, id, buy_price, trade_qty])

                qty -= trade_qty
                buy_qty -= trade_qty

                if buy_qty > 0:
                    # Resting buy order partially filled, push back
                    heapq.heappush(buy_book, (buy_price, buy_arrival, buy_id, buy_qty))
                    order_status[buy_id] = ('buy', buy_qty, buy_arrival, buy_price)
                else:
                    # Resting buy order fully filled
                    order_status[buy_id] = None
            else:
                break

        # If limit order, add remainder to book
        if qty > 0 and not is_ioc:
            add_to_sell_book(price, id, qty)
        else:
            if qty == 0:
                order_status[id] = None
            elif is_ioc:
                order_status[id] = None

    for order in orders:
        if order[0] == 'limit':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(id, price, qty, is_ioc=False)
            else:  # sell
                match_sell(id, price, qty, is_ioc=False)

        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(id, price, qty, is_ioc=True)
            else:  # sell
                match_sell(id, price, qty, is_ioc=True)

        elif order[0] == 'market':
            _, id, side, qty = order
            if side == 'buy':
                match_buy(id, float('inf'), qty, is_ioc=True)
            else:  # sell
                match_sell(id, 0, qty, is_ioc=True)

        elif order[0] == 'cancel':
            _, id = order
            if id in order_status and order_status[id] is not None:
                order_status[id] = None

        arrival_time += 1

    return trades

